// [MEDIUM_PRIORITY] CODE_QUALITY: Class structure reviewed
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.model/** * NOUS — Connectivity Data Models (Module 11 v3 — Step 11.1). * * All data types used by the Connectivity Layer. Pure data classes — * no logic, no Android dependencies. Fully testable. * * ## Model groups * *  1. **Contact** — ContactInfo, ContactGroup, ContactMatchResult. *  2. **Call** — CallInfo, CallState, CallDirection, CallType. *  3. **SMS** — SmsMessage, SmsStatus, SmsDirection. *  4. **SIM** — SimInfo, SimSlot, SimPreference. *  5. **Spam** — SpamClassification, SpamLevel. *  6. **Comms** — CommsEntry, CommsType, CommsInsight. *  7. **SOS** — SosTrigger, SosStatus. *  8. **Share** — ShareTarget, ShareContent. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§Architecture</a> */// ═══════════════════════════════════════════════════════════════════════════// 1. CONTACT MODELS// ═══════════════════════════════════════════════════════════════════════════/** * One contact from the device's contact list. * * @param id contact ID from ContactsContract. * @param displayName human-readable name ("Mom", "Rohit Sharma"). * @param phoneNumbers list of phone numbers associated with this contact. * @param primaryPhone the preferred phone number (first in list). * @param email optional email address. * @param isFavorite whether this contact is in favorites. * @param isTrusted whether this contact is in the "Trusted" list (voice verification relaxed). * @param preferredSimSlot which SIM to use for this contact (null = auto). * @param preferredMessagingApp preferred messaging app ("whatsapp", "telegram", "sms"). */data class ContactInfo(    val id: String,    val displayName: String,    val phoneNumbers: List<String>,    val email: String? = null,    val isFavorite: Boolean = false,    val isTrusted: Boolean = false,    val preferredSimSlot: SimSlot? = null,    val preferredMessagingApp: MessagingApp = MessagingApp.SMS,) {    init {        require(id.isNotBlank()) { "Contact id must not be blank" }        require(displayName.isNotBlank()) { "DisplayName must not be blank" }        require(phoneNumbers.isNotEmpty()) { "Contact must have at least one phone number" }    }    /** The primary phone number (first in list). */    val primaryPhone: String get() = phoneNumbers.first()}/** Result of a fuzzy contact search. */data class ContactMatchResult(    val contact: ContactInfo,    val matchScore: Float,    // 0.0-1.0 (1.0 = exact match)    val matchType: MatchType,)/** How a contact was matched. */enum class MatchType(val displayLabel: String) {    EXACT("Exact Match"),    NICKNAME("Nickname Match"),    FUZZY("Fuzzy Match"),    PHONE_NUMBER("Phone Number Match"),}/** Supported messaging apps for contact preference. */enum class MessagingApp(val displayLabel: String, val packageName: String?) {    SMS("SMS", null),    WHATSAPP("WhatsApp", "com.whatsapp"),    TELEGRAM("Telegram", "org.telegram.messenger"),    SIGNAL("Signal", "org.thoughtcrime.securesms"),}// ═══════════════════════════════════════════════════════════════════════════// 2. CALL MODELS// ═══════════════════════════════════════════════════════════════════════════/** Information about a phone call. */data class CallInfo(    val contact: ContactInfo?,    val phoneNumber: String,    val direction: CallDirection,    val type: CallType,    val timestampMs: Long,    val durationSeconds: Long = 0,    val isMissed: Boolean = false,    val isEmergency: Boolean = false,)/** Call direction. */enum class CallDirection(val displayLabel: String) {    INCOMING("Incoming"),    OUTGOING("Outgoing"),    MISSED("Missed"),}/** Call type. */enum class CallType(val displayLabel: String) {    STANDARD("Standard Call"),    WHATSAPP("WhatsApp Call"),    TELEGRAM("Telegram Call"),    EMERGENCY("Emergency Call"),}/** Live call state (monitored by CallStateMonitor). */enum class CallState(val displayLabel: String) {    IDLE("Idle"),    RINGING("Ringing"),    DIALING("Dialing"),    OFFHOOK("Connected"),    DISCONNECTED("Disconnected"),}// ═══════════════════════════════════════════════════════════════════════════// 3. SMS MODELS// ═══════════════════════════════════════════════════════════════════════════/** One SMS message. */data class SmsMessage(    val id: String,    val contact: ContactInfo?,    val phoneNumber: String,    val body: String,    val direction: SmsDirection,    val timestampMs: Long,    val status: SmsStatus = SmsStatus.SENT,    val isRead: Boolean = false,) {    init {        require(id.isNotBlank()) { "SMS id must not be blank" }        require(body.isNotBlank()) { "SMS body must not be blank" }    }}/** SMS direction. */enum class SmsDirection(val displayLabel: String) {    INCOMING("Incoming"),    OUTGOING("Outgoing"),}/** SMS delivery status. */enum class SmsStatus(val displayLabel: String) {    PENDING("Pending"),    SENT("Sent"),    DELIVERED("Delivered"),    FAILED("Failed"),}/** Smart reply suggestion (3 options generated by local LLM). */data class SmartReplySuggestion(    val replies: List<String>,   // exactly 3 suggestions    val source: SmartReplySource,    val contextPayload: String? = null,  // "Roshan is driving. ETA 15m." (Smart Payload v3))/** How smart replies were generated. */enum class SmartReplySource(val displayLabel: String) {    LOCAL_LLM("Local LLM"),    TEMPLATE("Template"),    CONTEXTUAL("Contextual (Smart Payload)"),}// ═══════════════════════════════════════════════════════════════════════════// 4. SIM MODELS// ═══════════════════════════════════════════════════════════════════════════/** Information about a SIM card slot. */data class SimInfo(    val slot: SimSlot,    val carrierName: String,    // "Jio", "Airtel", "Vi"    val displayName: String,    // "Personal", "Work" (user-assigned)    val isActive: Boolean,    val phoneNumber: String?,)/** SIM slot identifier. */enum class SimSlot(val slotIndex: Int) {    SIM1(0),    SIM2(1);    companion object {        fun fromIndex(index: Int): SimSlot? = entries.firstOrNull { it.slotIndex == index }    }}/** Per-contact SIM preference. */data class SimPreference(    val contactId: String,    val preferredSlot: SimSlot,    val isAutoLearned: Boolean,  // true if NOUS auto-detected from usage patterns)// ═══════════════════════════════════════════════════════════════════════════// 5. SPAM MODELS// ═══════════════════════════════════════════════════════════════════════════/** Spam classification result for a phone number. */data class SpamClassification(    val phoneNumber: String,    val level: SpamLevel,    val confidence: Float,      // 0.0-1.0    val reason: String,         // "Reported by 500+ users" or "Pattern: 200 calls/hour"    val source: SpamSource,)/** * Spam severity level. * * Strategy v3 §"SpamDetectorEngine" requires exactly four levels: *   - `HAM` — known-good (in user's contacts). *   - `SUSPECT` — pattern-based or community-reported as low-confidence spam. *   - `SPAM` — confirmed spam (user-reported or pattern match >100 calls/h). *   - `FRAUD` — verified fraud (e.g., known scam numbers in starter DB). * * For backwards-compatibility with the original 5-level enum, the legacy * `SAFE` / `LOW_RISK` / `SUSPICIOUS` / `HIGH_RISK` aliases still exist as * deprecated aliases — callers (e.g., [com.roshan.persona.connectivity.call.CallEngine]) * route legacy callers through [shouldBlock] / [shouldAskUser] helpers. */enum class SpamLevel(val displayLabel: String) {    HAM("Ham"),    SUSPECT("Suspect"),    SPAM("Spam"),    FRAUD("Fraud"),    // ─── Legacy aliases (deprecated — use the 4 canonical levels above) ─────    @Deprecated("Use HAM", replaceWith = ReplaceWith("HAM"))    SAFE("Safe"),    @Deprecated("Use SUSPECT", replaceWith = ReplaceWith("SUSPECT"))    LOW_RISK("Low Risk"),    @Deprecated("Use SUSPECT", replaceWith = ReplaceWith("SUSPECT"))    SUSPICIOUS("Suspicious"),    @Deprecated("Use FRAUD", replaceWith = ReplaceWith("FRAUD"))    HIGH_RISK("High Risk");    /** True if this level should be auto-rejected by the Bouncer (SPAM + FRAUD). */    val shouldAutoReject: Boolean        get() = this == SPAM || this == FRAUD    /** True if this level should trigger a "ask user" prompt (SUSPECT). */    val shouldAskUser: Boolean        get() = this == SUSPECT}/** * 3-mode Bouncer policy (Strategy §"Active AI Call Screening"). * * Replaces the binary `autoBlockSpam: Boolean` toggle with a 3-state enum: * *  - `OFF` — never auto-reject; ring normally and let the user decide. *  - `SUSPECT_AND_SPAM` — auto-reject both SUSPECT and SPAM/FRAUD calls. *  - `SPAM_ONLY` — only auto-reject SPAM/FRAUD; let SUSPECT ring normally *    so the user has a chance to identify false positives. */enum class BouncerMode(val displayLabel: String) {    OFF("Off"),    SUSPECT_AND_SPAM("Suspect + Spam"),    SPAM_ONLY("Spam Only");    /** True if the given [level] should be auto-rejected under this mode. */    fun shouldReject(level: SpamLevel): Boolean = when (this) {        OFF -> false        SPAM_ONLY -> level == SpamLevel.SPAM || level == SpamLevel.FRAUD        SUSPECT_AND_SPAM -> level == SpamLevel.SUSPECT ||            level == SpamLevel.SPAM ||            level == SpamLevel.FRAUD    }}/** How spam was detected. */enum class SpamSource(val displayLabel: String) {    LOCAL_DB("Local Database"),    PATTERN("Pattern Detection"),    ML_CLASSIFIER("ML Classifier"),    COMMUNITY("Community Report"),    CONTACT_LIST("In Contacts (Safe)"),}// ═══════════════════════════════════════════════════════════════════════════// 6. COMMS HISTORY MODELS// ═══════════════════════════════════════════════════════════════════════════/** One entry in the unified comms timeline. */data class CommsEntry(    val id: String,    val type: CommsType,    val contact: ContactInfo?,    val phoneNumber: String,    val summary: String,        // "Called Mom (5 min)" or "SMS: I'll be late"    val timestampMs: Long,    val direction: CallDirection?,  // null for non-call entries)/** Type of comms entry. */enum class CommsType(val displayLabel: String) {    CALL("Call"),    SMS("SMS"),    WHATSAPP("WhatsApp"),    TELEGRAM("Telegram"),    VOICEMAIL("Voicemail"),}/** Comms insight (behavioral analytics). */data class CommsInsight(    val type: InsightType,    val description: String,    // "You talk to Mom 5× more than Dad"    val confidence: Float,)/** Types of comms insights. */enum class InsightType(val displayLabel: String) {    FREQUENCY("Frequency Insight"),    RESPONSE_TIME("Response Time Insight"),    USAGE_PATTERN("Usage Pattern"),    RELATIONSHIP("Relationship Insight"),    NEGLECT("Neglect Alert"),}// ═══════════════════════════════════════════════════════════════════════════// 7. SOS MODELS// ═══════════════════════════════════════════════════════════════════════════/** SOS trigger state. */data class SosTrigger(    val emergencyContacts: List<String>,  // phone numbers    val locationEnabled: Boolean,    val autoRecordEnabled: Boolean,    val countdownSeconds: Int = 5,  // v3: 5-second cancelable countdown)/** SOS dispatch status. */enum class SosStatus(val displayLabel: String) {    COUNTDOWN("Countdown Active"),    CANCELLED("Cancelled"),    DISPATCHED("Dispatched"),    LOCATION_SHARING("Sharing Location"),    COMPLETED("Completed"),}// ═══════════════════════════════════════════════════════════════════════════// 8. SHARE MODELS// ═══════════════════════════════════════════════════════════════════════════/** A share target (app or contact). */data class ShareTarget(    val appName: String,    val packageName: String,    val isRecommended: Boolean,  // NOUS recommends this target    val reason: String? = null,  // "Best for photos" / "Rohit is online")/** Content to share. */data class ShareContent(    val text: String?,    val imageUri: String?,    val fileUri: String?,    val mimeType: String,) {    init {        require(text != null || imageUri != null || fileUri != null) {            "At least one of text/imageUri/fileUri must be non-null"        }    }}